mapper.select:
SELECT id,owner_member_id,upload_request_id,upload_receipt_hash,media_type,object_key,derived_object_key,mime_type,byte_size,
       width,height,duration_ms,alt_text,upload_state,review_state
FROM community_post_media WHERE owner_member_id=#{ownerMemberId} AND upload_request_id=#{uploadRequestId}

SELECT id,owner_member_id,upload_request_id,upload_receipt_hash,media_type,object_key,derived_object_key,
       mime_type,byte_size,width,height,duration_ms,alt_text,upload_state,review_state
FROM community_post_media WHERE upload_receipt_hash=#{uploadReceiptHash}

SELECT , , #{mode} feed_source, CASE WHEN #{mode}='FOLLOWING' THEN 'FOLLOWED_AUTHOR' WHEN #{mode}='NEARBY' THEN 'SAME_CITY' WHEN #{mode}='TOPIC' THEN 'FOLLOWED_TOPIC' WHEN #{mode}='COMMUNITY' THEN 'JOINED_COMMUNITY' WHEN #{mode}='FEATURED' THEN 'EDITOR_PICK' WHEN #{mode}='TRENDING' THEN 'HEALTHY_TREND' WHEN #{mode}='FOR_YOU' THEN 'RELEVANT_EXPLORATION' ELSE 'CHRONOLOGICAL' END reason_code, (p.like_count + p.bookmark_count*2 + p.comment_count*2) trending_score FROM community_post p LEFT JOIN ums_member m ON m.id=p.author_id WHERE p.lifecycle='PUBLISHED'
AND ((p.like_count + p.bookmark_count*2 + p.comment_count*2) < #{cursorScore} OR ((p.like_count + p.bookmark_count*2 + p.comment_count*2) = #{cursorScore} AND p.id < #{cursor}))
AND p.id < #{cursor}
AND p.author_id=#{authorId}
AND p.search_eligible=1 AND EXISTS( SELECT 1 FROM community_search_document sd WHERE sd.document_type='POST' AND sd.document_id=p.id AND sd.visibility_state='VISIBLE' AND sd.search_text LIKE CONCAT('%',#{keyword},'%'))
AND EXISTS(SELECT 1 FROM ums_member_follow f WHERE f.member_id=#{viewerId} AND f.follow_member_id=p.author_id)
AND p.city_code=#{cityCode}
AND EXISTS(SELECT 1 FROM community_post_topic pt WHERE pt.post_id=p.id AND pt.topic_code=#{topicCode})
AND p.community_id=#{communityId}
AND EXISTS(SELECT 1 FROM community_featured_entry fe WHERE fe.post_id=p.id AND fe.collection_code=#{collectionCode} AND fe.starts_at<=NOW() AND (fe.ends_at IS NULL OR fe.ends_at>NOW()))
AND p.recommendation_eligible=1
ORDER BY (p.like_count + p.bookmark_count*2 + p.comment_count*2) DESC,p.id DESC
ORDER BY p.id DESC
LIMIT #{limit}

SELECT , , ,
       'OWN_POSTS' feed_source, 'AUTHOR_WORKSPACE' reason_code
FROM community_post p LEFT JOIN ums_member m ON m.id=p.author_id
WHERE p.author_id=#{viewerId}
  AND p.lifecycle IN ('DRAFT','CHECKING','PUBLISHED','LIMITED','HIDDEN','REMOVED')
AND p.id < #{cursor}
ORDER BY p.id DESC LIMIT #{limit}

SELECT COUNT(*) FROM community_post_enforcement
WHERE target_member_id=#{memberId} AND status='ACTIVE' AND starts_at<=#{now}
  AND (ends_at IS NULL OR ends_at>#{now})
  AND enforcement_type IN
  #{type}

mapper.update:
UPDATE community_post_media SET post_id=NULL,sort_order=0,upload_state='COMMITTED',update_time=#{now}
WHERE post_id=#{postId} AND owner_member_id=#{ownerMemberId}

  AND id NOT IN
  #{mediaId}

UPDATE community_post SET audit_level=COALESCE(#{auditLevel},audit_level),
  audit_before_publish=COALESCE(#{auditBeforePublish},audit_before_publish),
  review_flag=COALESCE(#{reviewFlag},review_flag),update_time=#{now}
WHERE id=#{postId}

choose.when:
SELECT p.id,p.name,p.city_code,COALESCE(p.address,p.description,'') subtitle
FROM roam_poi p WHERE p.status=1 AND p.city_code IS NOT NULL AND p.city_code<>''
ORDER BY p.id DESC LIMIT #{limit}

SELECT m.id,m.nickname name,'' subtitle
FROM ums_member_follow f JOIN ums_member m ON m.id=f.follow_member_id
WHERE f.member_id=#{memberId}
ORDER BY m.id DESC LIMIT #{limit}

mapper.select:
SELECT id,event_id,aggregate_type,aggregate_id,event_type,payload_json,attempt_count FROM community_post_outbox
WHERE state IN ('PENDING','RETRY') AND next_attempt_at<=#{now}
ORDER BY id LIMIT #{limit}

mapper.update:
UPDATE community_post_outbox SET state=CASE WHEN attempt_count>=10 THEN 'DEAD' ELSE 'RETRY' END,
  last_error_code=#{errorCode},next_attempt_at=#{nextAttemptAt},update_time=#{now}
WHERE id=#{id} AND state='PROCESSING'

UPDATE community_notification n SET n.actor_count=(
  SELECT COUNT(*) FROM community_notification_actor a
  WHERE a.recipient_member_id=#{recipientMemberId} AND a.notification_type=#{notificationType}
    AND a.aggregate_key=#{aggregateKey}
),n.update_time=#{now}
WHERE n.recipient_member_id=#{recipientMemberId} AND n.notification_type=#{notificationType}
  AND n.aggregate_key=#{aggregateKey}

UPDATE community_post_revision r JOIN community_post p ON p.id=r.post_id
SET r.editor_member_id=0,r.immutable_snapshot_json=JSON_OBJECT('erased',TRUE),r.edit_reason=NULL
WHERE p.author_id=#{memberId} OR r.editor_member_id=#{memberId}

UPDATE community_post_appeal
SET reason='[erased]',evidence_asset_ids_json='[]',update_time=CURRENT_TIMESTAMP
WHERE appellant_member_id=#{memberId}
   OR enforcement_id IN (
     SELECT e.id FROM community_post_enforcement e
     LEFT JOIN community_post p ON p.id=e.post_id
     WHERE e.target_member_id=#{memberId} OR p.author_id=#{memberId}
   )

UPDATE community_post_appeal
SET appellant_member_id=0,request_id=CONCAT('erased-appeal-',id),update_time=CURRENT_TIMESTAMP
WHERE appellant_member_id=#{memberId}

UPDATE community_post_comment SET author_id=0,client_request_id=CONCAT('erased-comment-',id),body='',
  lifecycle='DELETED',author_approval_state='HIDDEN',deleted_at=COALESCE(deleted_at,#{now}),update_time=#{now},version=version+1
WHERE author_id=#{memberId}

UPDATE community_post_media m JOIN community_post p ON p.id=m.post_id
SET m.retention_state='ORPHANED',m.delete_after=#{deleteAfter},m.update_time=#{now}
WHERE p.author_id=#{memberId} AND m.retention_state='ACTIVE'

mapper.insert:
INSERT INTO community_erasure_job(subject_member_id,post_id,trigger_type,request_id,legal_hold,checklist_json,
  state,attempt_count,next_attempt_at,create_time,update_time)
SELECT #{memberId},p.id,'ACCOUNT_DEREGISTER',CONCAT(#{requestPrefix},'-',p.id),0,
  '{"search":true,"notifications":true,"mediaAfterDays":30}','PENDING',0,#{now},#{now},#{now}
FROM community_post p WHERE p.author_id=#{memberId}
ON DUPLICATE KEY UPDATE request_id=VALUES(request_id)

mapper.select:
SELECT id,subject_member_id,post_id,trigger_type,legal_hold,attempt_count FROM community_erasure_job
WHERE state IN ('PENDING','RETRY') AND next_attempt_at<=#{now}
ORDER BY id LIMIT #{limit}

SELECT id,object_key FROM community_post_media
WHERE post_id=#{postId} AND retention_state='ORPHANED' AND delete_after<=#{now}
ORDER BY id

mapper.update:
UPDATE community_post_media
SET owner_member_id=0,upload_request_id=CONCAT('erased-media-',id),upload_receipt_hash=NULL,
    object_key=CONCAT('deleted://',id),derived_object_key=NULL,alt_text=NULL,
    mime_type='application/octet-stream',byte_size=0,
    content_hash=SHA2(CONCAT('deleted:',id),256),retention_state='DELETED',update_time=#{now}
WHERE post_id=#{postId} AND retention_state='ORPHANED' AND delete_after<=#{now}

UPDATE community_erasure_job SET state=#{state},last_error_code=#{errorCode},
  next_attempt_at=#{nextAttemptAt},update_time=#{now}
WHERE id=#{id} AND state='PROCESSING'

mapper.select:
SELECT id,post_id,author_id,root_id,parent_id,replied_to_member_id,client_request_id,body,lifecycle,
       author_approval_state,version,create_time
FROM community_post_comment WHERE author_id=#{authorId} AND client_request_id=#{clientRequestId}

mapper.update:
UPDATE community_post_comment c SET like_count=(
  SELECT COUNT(*) FROM community_post_comment_action a WHERE a.comment_id=c.id AND a.action_type='LIKE'
) WHERE c.id=#{commentId}

UPDATE community_post_appeal SET status=#{decision},decision_reason=#{reason},reviewer_user_id=#{reviewerUserId},
  reviewed_at=#{now},update_time=#{now},version=version+1
WHERE id=#{id} AND status IN ('SUBMITTED','REVIEWING') AND version=#{expectedVersion}

mapper.select:
SELECT enforcement_type FROM community_post_enforcement
WHERE post_id=#{postId} AND status='ACTIVE' AND starts_at<=#{now}
  AND (ends_at IS NULL OR ends_at>#{now})

mapper.update:
UPDATE community_post_enforcement SET update_time=#{now}
WHERE post_id=#{postId} AND status='ACTIVE' AND starts_at<=#{now} AND update_time<starts_at
  AND (ends_at IS NULL OR ends_at>#{now})
